 const schema={'@context':'https://schema.org','@graph':[{'@type':'BlogPosting','@id':url+'#article',headline:a.title,description:a.description,url,inLanguage:lang,datePublished:a.published,dateModified:a.published,author:{'@type':'Organization',name:'COR HOMES',url:base+'/'},publisher:{'@type':'Organization',name:'COR HOMES',url:base+'/'},mainEntityOfPage:{'@id':url+'#webpage'},isPartOf:{'@type':'Blog','@id':base+prefix+'/blog#blog',url:base+prefix+'/blog',name:(lang==='ca'?"COR HOMES · Guies i consells":'COR HOMES · Guías y consejos')},citation:a.sources.map(s=>s[1])},{'@type':'WebPage','@id':url+'#webpage',url,name:a.title,inLanguage:lang,mainEntity:{'@id':url+'#article'},breadcrumb:{'@id':url+'#breadcrumbs'}},{'@type':'BreadcrumbList','@id':url+'#breadcrumbs',itemListElement:[{'@type':'ListItem',position:1,name:(lang==='ca'?"Inici":'Inicio'),item:base+(prefix||'/')},{'@type':'ListItem',position:2,name:'Blog',item:base+prefix+'/blog'},{'@type':'ListItem',position:3,name:a.title,item:url}]}]};
